(()=>{const ids=['temperature','heatmap','models'];function activate(id){for(const kind of ids){const active=kind===id;document.getElementById(kind+'-tab').setAttribute('aria-selected',String(active));document.getElementById(kind+'-tab').tabIndex=active?0:-1;document.getElementById(kind+'-panel').hidden=!active}}for(const id of ids){const b=document.getElementById(id+'-tab');b.addEventListener('click',()=>activate(id));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?2:(ids.indexOf(id)+(e.key==='ArrowRight'?1:2))%3;activate(ids[n]);document.getElementById(ids[n]+'-tab').focus()}})}const metrics={RMSLE:[1.3733,1.2649],MAE:[13086,12750],R2:[0.000346,0.004976]},names=['Random Forest (log target)','GBT (log target)'],NS='http://www.w3.org/2000/svg';function draw(){const key=document.getElementById('pdf-metric').value,v=metrics[key],max=Math.max(...v),s=document.createElementNS(NS,'svg');s.setAttribute('viewBox','0 0 500 215');s.setAttribute('role','img');s.setAttribute('aria-label',`${key}: Random Forest ${v[0]}, GBT ${v[1]}. Reported PDF values.`);function add(t,a,txt){const n=document.createElementNS(NS,t);for(const[k,v]of Object.entries(a))n.setAttribute(k,v);if(txt!==undefined)n.textContent=txt;s.append(n);return n}v.forEach((x,i)=>{const y=25+i*90;add('text',{x:5,y},names[i]);const r=add('rect',{x:5,y:y+15,width:335*x/max,height:25,rx:3,fill:i?'#345eea':'#809c88'}),title=document.createElementNS(NS,'title');title.textContent=`${names[i]}: ${x} ${key}`;r.append(title);add('text',{x:360,y:y+33},String(x))});document.getElementById('pdf-model-chart').replaceChildren(s);document.getElementById('pdf-model-detail').textContent=key==='R2'?'Both R² values are close to zero: predictive fit remains weak despite the difference between these experiments.':key==='MAE'?'Reported MAE is in source target units. Lower error for GBT in this comparison does not establish production readiness.':'GBT has lower reported RMSLE in this log-target comparison. The PDF notes that differences were not consistent across splits.'}document.getElementById('pdf-metric').addEventListener('change',draw);draw()})();
